 70#MW:  background:var(--color-background-primary);
 71#RK:  border:0.5px solid var(--color-border-tertiary);
 72#JS:  border-radius:var(--border-radius-lg); overflow:hidden;
 73#MB:  cursor:pointer; transition:border-color 0.15s;
 74#XK:}
