 91#WZ:.test-badges { display:flex; gap:5px; flex-wrap:wrap; margin-top:5px; }
 92#WN:.badge { font-size:10px; font-weight:500; padding:2px 8px; border-radius:100px; }
 93#TX:.b-blue { background:#E6F1FB; color:#185FA5; }
 94#ZV:.b-green { background:#EAF3DE; color:#3B6D11; }
 95#JV:.b-amber { background:#FAEEDA; color:#854F0B; }
 96#BK:.b-pink { background:#FBEAF0; color:#993556; }
 97#RT:.b-teal { background:#E1F5EE; color:#0F6E56; }
 98#RV:@media(prefers-color-scheme:dark){
 99#XM:  .b-blue{background:#042C53;color:#B5D4F4;}
100#BZ:  .b-green{background:#173404;color:#C0DD97;}
101#RM:  .b-amber{background:#412402;color:#FAC775;}
102#RH:  .b-pink{background:#4B1528;color:#F4C0D1;}
103#HP:  .b-teal{background:#04342C;color:#9FE1CB;}
104#VV:}
