114#PS:.mini-lbl { font-size:10px; font-weight:500; text-transform:uppercase; letter-spacing:0.06em; color:var(--color-text-tertiary); margin-bottom:3px; }
115#TY:.mini-val { font-size:12px; color:var(--color-text-secondary); line-height:1.5; }
116#NV:.results-row { display:flex; flex-wrap:wrap; gap:6px; margin-top:8px; }
117#ZS:.result-tag {
118#JR:  font-size:12px; padding:5px 12px; border-radius:var(--border-radius-md);
119#RK:  border:0.5px solid var(--color-border-tertiary);
120#PT:  color:var(--color-text-secondary); background:var(--color-background-secondary);
121#HM:  line-height:1.4;
