155#XK:/* ── Virality ── */
156#ZT:.viral-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-bottom:20px; }
157#HH:.viral-card {
158#MW:  background:var(--color-background-primary);
159#RK:  border:0.5px solid var(--color-border-tertiary);
160#BX:  border-radius:var(--border-radius-lg); padding:14px 16px;
161#NZ:}
162#XQ:.viral-title { font-size:13px; font-weight:500; color:var(--color-text-primary); margin:0 0 6px; display:flex; align-items:center; gap:6px; }
163#ST:.viral-desc { font-size:12px; color:var(--color-text-secondary); line-height:1.5; margin:0; }
